"""rust_highlight.compute_spans — pure Rust tokenizer for the viewer."""

from resnik_ide.rust_highlight import compute_spans

SRC = (
    "// generated by resnik\n"                      # 1
    "#![no_std]\n"                                  # 2
    "fn main() {\n"                                 # 3
    "    let x: i32 = 0x1F + 2;\n"                  # 4
    "    println!(\"hi {}\", x); /* done */\n"      # 5
    "    let c = 'a';\n"                            # 6
    "}\n"
)


def _by(spans):
    out = {}
    for t, a, b in spans:
        out.setdefault(t, []).append((a, b))
    return out


class TestRust:
    def test_tags(self):
        by = _by(compute_spans(SRC))
        assert by["hl_comment"] == [("1.0", "1.22"), ("5.26", "5.36")]
        assert by["hl_directive"] == [("2.0", "2.10")]
        assert ("3.0", "3.2") in by["hl_keyword"]          # fn
        assert ("4.4", "4.7") in by["hl_keyword"]          # let
        assert ("4.11", "4.14") in by["hl_type"]           # i32
        assert ("4.17", "4.21") in by["hl_number"] and ("4.24", "4.25") in by["hl_number"]
        assert by["hl_macro"] == [("5.4", "5.12")]         # println!
        assert ("5.13", "5.20") in by["hl_string"]         # "hi {}"
        assert ("6.12", "6.15") in by["hl_string"]         # 'a'
        assert "main" not in str(by)                       # plain identifiers untagged

    def test_empty_and_huge(self):
        assert compute_spans("") == []
        assert compute_spans("x" * (2 * 1024 * 1024)) == []

    def test_lifetimes_are_not_strings(self):
        by = _by(compute_spans("fn f<'a>(s: &'a str) -> &'a str { s }\n"))
        assert "hl_string" not in by
        assert ("1.0", "1.2") in by["hl_keyword"]
        assert by["hl_type"] and all(a.startswith("1.") for a, _ in by["hl_type"])
